LESSONS = [
 dict(day=1,title='Introduction to Python',en='Python runs instructions from top to bottom. A string is text inside quotes. print displays a value in the console.',ta='Python கட்டளைகளை மேலிருந்து கீழாக இயக்கும். மேற்கோளுக்குள் உள்ள உரை string ஆகும். print ஒரு மதிப்பை வெளியிடும்.',example='print("Hello, Python!")',task='Greet the island guardian by printing Hello, Python!',expected='Hello, Python!',question='What does print do?',options=['Displays a value','Deletes a file','Creates a loop'],answer=0),
 dict(day=2,title='print() and Comments',en='Pass multiple values to print with commas. Python adds spaces between them. A comment begins with # and is ignored during execution.',ta='print-க்கு பல மதிப்புகளை காற்புள்ளியால் பிரித்துக் கொடுக்கலாம். அவற்றுக்கு இடையில் இடைவெளி வரும். # தொடங்கும் குறிப்பு இயக்கப்படாது.',example='# Greet your companion\nprint("Hello", "explorer")',task='Print Hello explorer using two arguments.',expected='Hello explorer',question='Which character starts a comment?',options=['@','#','$'],answer=1),
 dict(day=3,title='Variables',en='A variable names a value. Use = to assign a value. Reassigning a name replaces its previous value. Names are case-sensitive.',ta='ஒரு மதிப்புக்கு பெயர் கொடுப்பதே variable. = மூலம் மதிப்பை ஒதுக்கலாம். மீண்டும் ஒதுக்கினால் பழைய மதிப்பு மாறும். பெரிய, சிறிய எழுத்துகள் வேறுபடும்.',example='damage = 50\nprint(damage)',task='Set damage to 50 and print its value.',expected='50',question='Which statement assigns 50 to damage?',options=['damage == 50','50 = damage','damage = 50'],answer=2),
 dict(day=4,title='Data Types',en='int stores whole numbers, float stores decimal numbers, str stores text and bool stores True or False. type reports the type of a value.',ta='int முழு எண்களையும் float தசம எண்களையும் str உரையையும் bool True அல்லது False மதிப்பையும் சேமிக்கும். type மதிப்பின் வகையைக் காட்டும்.',example='coins = 12\nprint(type(coins).__name__)',task='Print the type name of the integer 12.',expected='int',question='What is the type of 3.5?',options=['int','float','bool'],answer=1),
 dict(day=5,title='Input and Type Conversion',en='input returns text. Convert numeric text with int or float before arithmetic. Invalid numeric text raises ValueError. This example uses saved input so it runs without a prompt.',ta='input உரையாக மதிப்பைத் தரும். கணக்கிடும் முன் int அல்லது float மூலம் மாற்றவும். எண்ணாக மாற்ற முடியாத உரை ValueError தரும். இங்கு சேமித்த உள்ளீடு பயன்படுத்தப்படுகிறது.',example='saved_input = "7"\ncoins = int(saved_input)\nprint(coins + 3)',task='Convert the text 7 to an integer, add 3 and print the result.',expected='10',question='What does int("7") return?',options=['The integer 7','The string 7','An error'],answer=0)
]

# Each row contains a distinct executable lesson, bilingual explanation and assessment.
_MORE = [
('Strings','Text supports indexing from zero and slicing; strings are immutable.','உரையில் முதல் எழுத்தின் index பூஜ்ஜியம். slice மூலம் பகுதியைப் பெறலாம்; string-ஐ நேரடியாக மாற்ற முடியாது.','name = "Python"\nprint(name[:3])','Print the first three letters of Python.','Pyt','What is the first index?', ['0','1','-2'],0),
('String Methods','Methods return transformed text. strip removes edge whitespace and upper converts letters to uppercase.','strip ஓரங்களில் உள்ள இடைவெளியை நீக்கும். upper எழுத்துகளை பெரிய எழுத்துகளாக மாற்றும்.','name = "  python  "\nprint(name.strip().upper())','Clean and capitalize the text python.','PYTHON','Which method removes edge spaces?',['upper','strip','split'],1),
('Lists','Lists are ordered, mutable collections. append adds one item and len counts items.','List வரிசையுள்ள மாற்றக்கூடிய தொகுப்பு. append ஒரு உறுப்பைச் சேர்க்கும்; len எண்ணிக்கையைத் தரும்.','bag = ["key", "map"]\nbag.append("gem")\nprint(len(bag))','Add a gem to a two-item inventory and print its size.','3','Which method adds an item?',['append','strip','keys'],0),
('Tuples and Sets','Tuples cannot change their elements. Sets remove duplicates and do not promise insertion order.','Tuple உறுப்புகளை மாற்ற முடியாது. Set நகல்களை நீக்கும்; சேர்த்த வரிசையை உறுதி செய்யாது.','gems = {"red", "red", "blue"}\nprint(len(gems))','Count distinct gem colors.','2','Which collection removes duplicates?',['list','tuple','set'],2),
('Dictionaries','A dictionary maps unique keys to values. Access a value using its key; get can supply a default.','Dictionary தனித்த key-களை value-களுடன் இணைக்கும். key மூலம் மதிப்பைப் பெறலாம்; get இயல்புநிலை தரலாம்.','hero = {"coins": 20}\nprint(hero.get("coins", 0))','Look up and print the hero coin count.','20','What does a dictionary map?',['Keys to values','Only numbers','Only indexes'],0),
('Operators','Arithmetic operators include +, -, *, /, // and %. Floor division gives a rounded-down quotient; remainder uses %.','கணித operators-ல் +, -, *, /, //, % உள்ளன. // கீழ்நோக்கி முழு ஈவைத் தரும்; % மீதியைத் தரும்.','print(17 // 5)\nprint(17 % 5)','Divide 17 coins into groups of five and print groups and remainder.','3\n2','Which operator finds the remainder?',['/','%','**'],1),
('Comparison Operators','Comparisons produce booleans. == checks equality while = assigns. != means not equal.','ஒப்பீடுகள் boolean மதிப்பைத் தரும். == சமமா எனச் சோதிக்கும்; = ஒதுக்கும். != சமமில்லை என்பதாகும்.','coins = 10\nprint(coins >= 10)','Print whether ten coins meet a ten-coin entrance price.','True','Which operator compares equality?',['=','==','+='],1),
('If, Elif and Else','Conditions choose a branch. Indentation defines the body. elif tries another condition and else is the fallback.','நிபந்தனை ஒரு கிளையைத் தேர்ந்தெடுக்கும். உள்தள்ளல் அதன் உடலைக் குறிக்கும். elif அடுத்த சோதனை; else மீதமுள்ள நிலை.','coins = 10\nif coins >= 10:\n    print("Open")\nelse:\n    print("Locked")','Open the gate when coins are at least ten.','Open','What defines a Python block?',['Braces','Indentation','Commas'],1),
('Nested Conditions','A conditional can contain another conditional. Both conditions must succeed to enter the inner body.','ஒரு நிபந்தனைக்குள் மற்றொன்று இருக்கலாம். உள்ளேயுள்ள கட்டளையை இயக்க இரண்டும் சரியாக வேண்டும்.','has_key = True\nhealth = 8\nif has_key:\n    if health > 0:\n        print("Enter")','Enter only with a key and positive health.','Enter','When does the inner body run?',['Always','When both tests pass','Never'],1),
('For and While Loops','for visits items in an iterable. while repeats while its condition holds. Update while-loop state to avoid endless execution.','for தொகுப்பின் உறுப்புகளைச் சுற்றும். while நிபந்தனை சரியாக இருக்கும் வரை தொடரும். முடிவில்லா சுழற்சியைத் தவிர்க்க நிலையை மாற்றவும்.','for coin in range(1, 4):\n    print(coin)','Print the coin numbers one through three.','1\n2\n3','Does range(1,4) include 4?',['Yes','No','Only sometimes'],1),
('Loop Challenges','An accumulator combines values across iterations. Initialize it before the loop; update it within the loop.','Accumulator ஒவ்வொரு சுற்றின் மதிப்பையும் சேர்க்கும். சுழற்சிக்கு முன் தொடங்கி உள்ளே புதுப்பிக்கவும்.','total = 0\nfor coin in [2, 4, 6]:\n    total += coin\nprint(total)','Sum three coin piles with a loop.','12','Where should a sum accumulator start?',['Inside every iteration','Before the loop','After print'],1),
('Functions','def creates reusable behavior. A function body runs when the function is called, not when it is defined.','def மீண்டும் பயன்படுத்தக்கூடிய செயல்பாட்டை உருவாக்கும். வரையறுக்கும் போது அல்ல, அழைக்கும் போது உடல் இயங்கும்.','def greet():\n    print("Ready")\ngreet()','Define and call a greeting ability.','Ready','What calls greet?',['def greet','greet()','return greet'],1),
('Function Arguments','Parameters name inputs in a definition. Arguments supply values at the call. Defaults are used when an argument is omitted.','Parameter வரையறையில் உள்ளீட்டுக்குப் பெயர் தரும். Argument அழைப்பில் மதிப்பை வழங்கும். விடுபட்டால் default பயன்படும்.','def greet(name="Hero"):\n    print("Hello", name)\ngreet("Ada")','Pass Ada to a greeting function.','Hello Ada','Which is an argument in greet("Ada")?',['greet','Ada','def'],1),
('Return Statements','return sends a value to the caller and ends the call. Printing displays text but does not replace a returned value.','return அழைத்த இடத்துக்கு மதிப்பை அனுப்பி அழைப்பை முடிக்கும். print வெளியிடும்; அது return மதிப்பாகாது.','def double(n):\n    return n * 2\nprint(double(6))','Return double the damage, then print it.','12','What does return do?',['Sends a value to caller','Only prints','Repeats forever'],0),
('Recursion Basics','A recursive function calls itself with a smaller problem. A base case stops recursion; without it calls may exceed the recursion limit.','Recursive function தன்னையே சிறிய பிரச்சினையுடன் அழைக்கும். Base case நிறுத்தும்; இல்லாவிட்டால் அழைப்பு வரம்பு மீறலாம்.','def factorial(n):\n    if n <= 1:\n        return 1\n    return n * factorial(n - 1)\nprint(factorial(4))','Compute factorial of four recursively.','24','Why is a base case needed?',['To stop recursion','To import modules','To print twice'],0),
('File Handling','with open closes a file even if a body raises an error. w replaces content; r reads it. Browser files live in temporary virtual storage.','with open பிழை வந்தாலும் கோப்பை மூடும். w உள்ளடக்கத்தை மாற்றும்; r படிக்கும். உலாவிக் கோப்புகள் தற்காலிக மெய்நிகர் சேமிப்பில் இருக்கும்.','with open("quest.txt", "w") as f:\n    f.write("Victory")\nwith open("quest.txt") as f:\n    print(f.read())','Save and read a victory note.','Victory','Which mode replaces a file?',['r','w','a'],1),
('Exception Handling','try runs risky code. except handles a specified exception. Catch a narrow exception so unrelated bugs remain visible.','try பிழை வரக்கூடிய code-ஐ இயக்கும். except குறிப்பிட்ட பிழையைக் கையாளும். தொடர்பற்ற பிழைகள் தெரிய குறுகிய exception-ஐப் பிடிக்கவும்.','try:\n    int("gem")\nexcept ValueError:\n    print("Invalid number")','Handle an invalid number without crashing.','Invalid number','What exception does int("gem") raise?',['KeyError','ValueError','IndexError'],1),
('Modules and Packages','Modules group Python definitions. import loads a module; use a dot to access a member. Packages organize modules.','Module Python வரையறைகளைத் தொகுக்கும். import ஏற்றும்; புள்ளி மூலம் உறுப்பை அணுகலாம். Package module-களை ஒழுங்குபடுத்தும்.','import math\nprint(math.isqrt(81))','Use the math module to find an integer square root.','9','How do you access sqrt from math?',['math.sqrt','math->sqrt','sqrt.math'],0),
('Object-Oriented Programming','Objects combine state and behavior. A class describes objects; methods receive the instance as self.','Object நிலையும் செயல்பாடும் ஒன்றாக வைத்திருக்கும். Class அதன் வடிவத்தைச் சொல்கிறது; method-க்கு self instance-ஐ வழங்கும்.','class Hero:\n    def cheer(self):\n        return "Go!"\nprint(Hero().cheer())','Give a hero a cheer method.','Go!','What does self refer to?',['The current instance','Every class','A module'],0),
('Classes and Objects','__init__ initializes new instances. Instance attributes belong to each object, allowing different heroes to have different names.','__init__ புதிய instance-ஐத் தொடங்கும். Instance attribute ஒவ்வொரு object-க்கும் தனி; வீரர்களுக்குத் தனிப் பெயர் தரலாம்.','class Hero:\n    def __init__(self, name):\n        self.name = name\nhero = Hero("Ada")\nprint(hero.name)','Create a named hero object.','Ada','When is __init__ called?',['At instance creation','Only at import','Never'],0),
('Inheritance','A subclass reuses a parent class and can override methods. Prefer inheritance when a child really is a specialized parent.','Subclass பெற்றோர் class-ஐ மீண்டும் பயன்படுத்தி method-ஐ மாற்றலாம். குழந்தை உண்மையில் சிறப்பு வகையாக இருந்தால் inheritance பொருத்தம்.','class Hero:\n    def attack(self):\n        return 10\nclass Mage(Hero):\n    def attack(self):\n        return 20\nprint(Mage().attack())','Override the mage attack damage.','20','Which method does Mage().attack() use?',['Mage override','Always parent','Neither'],0),
('Encapsulation and Polymorphism','Encapsulation keeps state behind a clear interface. A leading underscore signals internal use, not enforced privacy. Polymorphism lets different objects share a method name.','Encapsulation நிலையை தெளிவான interface பின்னால் வைக்கும். தொடக்க underscore உள் பயன்பாட்டுக் குறிப்பு; கட்டாயத் தனியுரிமை அல்ல. வேறு objects ஒரே method பெயரைப் பயன்படுத்தலாம்.','class Chest:\n    def __init__(self):\n        self._coins = 5\n    def balance(self):\n        return self._coins\nprint(Chest().balance())','Read chest coins through a method.','5','Does a single underscore enforce privacy?',['Yes','No','Only for integers'],1),
('Mini Projects','Break a project into input, transformation and output. Small functions are easier to test. This inventory summary combines lists, dictionaries and aggregation.','திட்டத்தை உள்ளீடு, மாற்றம், வெளியீடு எனப் பிரிக்கவும். சிறிய functions சோதிக்க எளிது. இங்கு list, dictionary, கூட்டல் இணைகின்றன.','items = [{"name": "gem", "price": 4}, {"name": "key", "price": 6}]\ndef total_cost(items):\n    return sum(item["price"] for item in items)\nprint(total_cost(items))','Calculate the total inventory price.','10','Why split a project into functions?',['Easier testing and reuse','To avoid all data','To disable errors'],0),
('Advanced Coding Challenges','A frequency dictionary counts repeated items in one pass. get returns zero for unseen keys. Consider empty input and repeated values when testing.','Frequency dictionary ஒரே சுற்றில் மீண்டும் வரும் உறுப்புகளை எண்ணும். புதிய key-க்கு get பூஜ்ஜியம் தரலாம். வெற்று உள்ளீடும் நகல்களும் சோதிக்கவும்.','counts = {}\nfor gem in ["red", "blue", "red"]:\n    counts[gem] = counts.get(gem, 0) + 1\nprint(counts["red"])','Count repeated red gems.','2','What should an unseen frequency start at?',['0','-1','100'],0),
('Final Python Boss Challenge','Combine classes, functions, loops and conditions. Track state explicitly, stop when the enemy is defeated and test that health cannot fall below zero.','Class, function, loop, condition-ஐ இணைக்கவும். நிலையை வெளிப்படையாக வைத்திருந்து எதிரி தோற்றதும் நிறுத்தவும்; health பூஜ்ஜியத்துக்குக் கீழ் போகாததைச் சோதிக்கவும்.','class Boss:\n    def __init__(self):\n        self.health = 30\n    def hit(self, damage):\n        self.health = max(0, self.health - damage)\nboss = Boss()\nfor damage in [10, 15, 10]:\n    boss.hit(damage)\nprint(boss.health)','Defeat the boss and print its remaining health.','0','Why use max(0, health - damage)?',['Prevent negative health','Double damage','Skip every attack'],0)
]
for day, row in enumerate(_MORE, 6):
    title,en,ta,example,task,expected,question,options,answer=row
    LESSONS.append(dict(day=day,title=title,en=en,ta=ta,example=example,task=task,expected=expected,question=question,options=options,answer=answer))
for lesson in LESSONS:
    lesson['world']=(lesson['day']-1)//5+1
    lesson['objectives']=[f"Explain {lesson['title'].lower()} in your own words",'Run and modify the working example','Solve the practice mission and pass the knowledge check']
    lesson['exercise']='Change one input in the example, predict the result, then run it to check your prediction.'
    lesson['mission']='Unlock the next knowledge crystal: '+lesson['task']

